# Simpler test
def predict_split_pattern(grid):
    cells_by_val = find_components_by_value(grid)

    first_positions = {}
    for val, cells in cells_by_val.items():
        first_positions[val] = (min(r for r, c in cells), min(c for r, c in cells))

    height = len(grid)
    width = len(grid[0])
    right_cols = list(range(width // 2, width))

    top_threshold = height // 3

    top_vals = []
    bottom_vals = []
    for val, (first_r, first_c) in first_positions.items():
        if first_r < top_threshold:
            top_vals.append(val)
        else:
            bottom_vals.append(val)

    top_vals = sorted(top_vals, key=lambda v: first_positions[v])
    bottom_vals = sorted(bottom_vals, key=lambda v: first_positions[v])

    top_target = right_cols[-1]  # Highest right col
    bottom_target = right_cols[0]  # Lowest right col

    output = [[0] * width for _ in range(height)]

    for val in top_vals:
        cells = cells_by_val[val]
        min_c_in = min(c for r, c in cells)
        shift = top_target - min_c_in
        for r, c in cells:
            if 0 <= r < height and 0 <= c + shift < width:
                output[r][c + shift] = val

    for val in bottom_vals:
        cells = cells_by_val[val]
        min_c_in = min(c for r, c in cells)
        shift = bottom_target - min_c_in
        for r, c in cells:
            if 0 <= r < height and 0 <= c + shift < width:
                output[r][c + shift] = val

    return output

